import React, { useState } from "react";
import "./Projects.css";

function Projects() {
  const [activeProject, setActiveProject] = useState(null);

  const projects = [
    {
      id: 1,
      title: "Credit Card Recommendation System",
      description:
        "This credit card recommendation system helps users find the best credit card based on their preferences. It uses data analysis, rule-based scoring, and filtering rather than AI.",
      previewImage: "/CreditCardMain.png",
      video: "/CreditCardVideo.mp4",
      images: ["/CreditCardMain.png", "/CreditCardResults.png"],
    },
    {
      id: 2,
      title: "Tradernal, Personalized Trading Journal",
      description:
        "Tradernal is a trading journal that helps users track trades, analyze performance, and improve strategy. It also includes a personalized AI coach that gives insights and feedback based on trading activity.",
      previewImage: "/TradernalMain.png",
      video: "/TradernalVideo.mp4",
      images: ["/TradernalMain.png", "/TradernalDashboard.png"],
    },
  ];

  const handlePopup = (projectId) => {
    setActiveProject(projectId);
  };

  const closePopup = () => {
    setActiveProject(null);
  };

  return (
    <section id="projects" className="projects">
      <h2>My Projects</h2>
      <div className="project-list">
        {projects.map((project) => (
          <div key={project.id} className="project-item">
            <div
              className="preview-container"
              onClick={() => handlePopup(project.id)}
            >
              <img
                src={project.previewImage}
                alt={`${project.title} Preview`}
                className="preview-image"
              />
              <div className="overlay">View Project</div>
            </div>
          </div>
        ))}
      </div>

      {activeProject && (
        <div className="popup-overlay" onClick={closePopup}>
          <div className="popup" onClick={(e) => e.stopPropagation()}>
            <div className="popup-content">
              {projects
                .filter((project) => project.id === activeProject)
                .map((project) => (
                  <div key={project.id}>
                    <h3>{project.title}</h3>
                    <p>{project.description}</p>

                    <div className="media-container">
                      <video
                        src={project.video}
                        controls
                        className="popup-video"
                      />
                      <div className="popup-images">
                        {project.images.map((image, index) => (
                          <img
                            key={index}
                            src={image}
                            alt={`${project.title} Screenshot ${index + 1}`}
                            className="popup-image"
                          />
                        ))}
                      </div>
                    </div>

                    <button onClick={closePopup}>Close</button>
                  </div>
                ))}
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

export default Projects;
